svg.script:
const svgNS = 'http://www.w3.org/2000/svg';
const chart = document.getElementById('chart');
function add(tag, attrs, parent = chart) {
  const el = document.createElementNS(svgNS, tag);
  for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
  parent.appendChild(el);
  return el;
}
const w = 1200, h = 820;
const margin = { top: 60, right: 40, bottom: 80, left: 120 };
const left = margin.left, right = w - margin.right, top = margin.top, bottom = h - margin.bottom;
const plotW = right - left, plotH = bottom - top;
add('line', { x1: left, y1: top, x2: left, y2: bottom, class: 'axis' });
add('line', { x1: left, y1: bottom, x2: right, y2: bottom, class: 'axis' });
add('line', { x1: left, y1: top, x2: right, y2: top, class: 'axis' });
add('line', { x1: right, y1: top, x2: right, y2: bottom, class: 'axis' });
const xTicks = [0,5,10,15,20];
xTicks.forEach(t => {
  const x = left + (t/20)*plotW;
  add('line', { x1: x, y1: top, x2: x, y2: bottom, class: 'grid' });
  const txt = add('text', { x, y: bottom + 34, 'text-anchor': 'middle', class: 'tick' });
  txt.textContent = t;
});
const yTicks = [14,15,16,17];
yTicks.forEach(t => {
  const y = bottom - ((t-14)/3)*plotH;
  add('line', { x1: left, y1: y, x2: right, y2: y, class: 'grid' });
  const txt = add('text', { x: left - 16, y: y + 7, 'text-anchor': 'end', class: 'tick' });
  txt.textContent = t;
});
const title = add('text', { x: w/2, y: 36, 'text-anchor': 'middle', class: 'label' });
title.textContent = 'Switching-SNR Sensitivity - Rayleigh';
const ylab = add('text', { x: 30, y: h/2, transform: `rotate(-90 30 ${h/2})`, 'text-anchor': 'middle', class: 'label' });
ylab.textContent = 'Switching SNR (dB)';
const xlab = add('text', { x: w/2, y: h - 20, 'text-anchor': 'middle', class: 'label' });
xlab.textContent = 'Target BER';

const xvals = [1e-2,1e-3,1e-4];
const yvals = [14,14,17];
function pt(vx, vy) {
  const px = left + ((Math.log10(vx)+2) / 4) * plotW;
  const py = bottom - ((vy-14)/3) * plotH;
  return `${px},${py}`;
}
add('polyline', { points: [pt(1e-2,14), pt(1e-3,14), pt(1e-4,17)].join(' '), fill: 'none', stroke: '#1f77b4', 'stroke-width': 2.5 });
add('polyline', { points: [pt(1e-2,14), pt(1e-3,14), pt(1e-4,17)].join(' '), fill: 'none', stroke: '#d62728', 'stroke-width': 2.5 });
const data = [
  ['circle', '#1f77b4', [14,14,17]],
  ['square', '#d62728', [14,14,17]]
];
data.forEach(([shape, color, arr]) => {
  arr.forEach((yval, idx) => {
    const xv = xvals[idx];
    const px = left + ((Math.log10(xv)+2) / 4) * plotW;
    const py = bottom - ((yval-14)/3) * plotH;
    if (shape === 'circle') add('circle', { cx: px, cy: py, r: 5, fill: 'none', stroke: color, 'stroke-width': 2 });
    if (shape === 'square') add('rect', { x: px - 5, y: py - 5, width: 10, height: 10, fill: 'none', stroke: color, 'stroke-width': 2 });
  });
});
const legend = add('g', {});
const lx = 820, ly = 120;
[['BPSK → QPSK','#1f77b4','circle'], ['QPSK → 16-QAM','#d62728','square']].forEach(([label,color,shape],idx) => {
  const xoff = idx*180;
  if (shape === 'circle') add('circle', { cx: lx + xoff + 18, cy: ly, r: 5, fill: 'none', stroke: color, 'stroke-width': 2 }, legend);
  if (shape === 'square') add('rect', { x: lx + xoff + 12, y: ly - 5, width: 10, height: 10, fill: 'none', stroke: color, 'stroke-width': 2 }, legend);
  const txt = add('text', { x: lx + xoff + 35, y: ly + 5, class: 'legend' }, legend);
  txt.textContent = label;
});
